namespace sv_b199893d52ec40738d031cb52ececf75.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts for the currently selected warehouse.
/// Polling is ref-counted: starts when the first subscriber requests it, stops when the
/// last one releases. Fires <see cref="OnAlertCountChanged"/> so all subscribed components
/// re-render — not just the one that triggered the poll.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private CancellationTokenSource? _cts;
    private int _pollingRefCount;
    private readonly object _lock = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>Simulates a database query — returns a random number between 0 and 15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component becomes visible and wants polling to run.
    /// Ref-counted so multiple callers are safe.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _pollingRefCount++;
            if (_pollingRefCount == 1)
            {
                _cts = new CancellationTokenSource();
                _ = PollLoopAsync(_cts.Token);
            }
        }
    }

    /// <summary>
    /// Call when a component is disposed or leaves the page.
    /// Polling stops when the last subscriber releases.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _pollingRefCount = Math.Max(0, _pollingRefCount - 1);
            if (_pollingRefCount == 0)
            {
                _cts?.Cancel();
                _cts?.Dispose();
                _cts = null;
            }
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        // Fetch immediately on start, then every 10 seconds.
        await FetchAndNotifyAsync();

        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped.
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount =
            await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private void HandleWarehouseChanged()
    {
        // Re-fetch immediately when the warehouse changes.
        _ = FetchAndNotifyAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

